beidax.source:
function beidax(flying)
{
   applyColors();
   if(_root.zhanting == true)
   {
      return undefined;
   }
   if(hitNear && time <= 5 && htx > 0)
   {
      _root.game["p" + pn].moveX((- htx) * 1.5);
   }
   else
   {
      _parent.moveX(- htx);
   }
   _parent.moveY(- yup);
   hstm++;
   if(!flying && hstm < 20)
   {
      doHurtSkill();
   }
   time++;
   if(time > 13)
   {
      yup = 0;
      if(!flying)
      {
         htx = 0;
      }
   }
   if(time > 15)
   {
      jump = 0;
   }
   if(flying)
   {
      if(touch == 1)
      {
         if(yup < 0)
         {
            if(hited == 1)
            {
               gotoAndStop("击落地");
               play();
            }
         }
         else if(time > 15)
         {
            gotoAndStop("击落地");
            play();
         }
      }
      return undefined;
   }
   if(time == 0 || tdtime == 0 || isNaN(tdtime))
   {
      play();
      return undefined;
   }
   if(time >= tdtime)
   {
      play();
   }
}

