onDashing.source:
function onDashing()
{
   if(++dashF < 10)
   {
      if(dashY != 0)
      {
         _parent.moveY(dashY);
         hitBan = false;
         touch = false;
         gotoAndStop("落");
      }
      else
      {
         _parent.moveX(dashX);
         gotoAndStop("走");
      }
      _parent.showdow({R:20,G:-100,B:255});
   }
   else
   {
      _root.bsw(pn,false);
      dashing = false;
      updateDirect();
      if(dashY != 0)
      {
         gotoAndStop("落2");
         play();
      }
      else
      {
         updateDirect();
         gotoAndStop("站立");
         play();
      }
   }
}

